<?php
session_start();
require '../../config/db.php';
if(!isset($_SESSION['admin_id'])){header('Location: ../../auth/login-admin.php');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$q=trim($_GET['q']??'');$params=[];$where='';
if($q!==''){$where='WHERE s.protocolo LIKE ? OR s.titulo LIKE ? OR s.equipamento LIKE ? OR s.solicitante_nome LIKE ? OR c.nome LIKE ?';$like='%'.$q.'%';$params=[$like,$like,$like,$like,$like];}
$stmt=$pdo->prepare("SELECT s.*,c.nome cliente_nome,a.nome registrado_por_nome,t.nome tecnico_nome FROM solicitacoes s JOIN clientes c ON c.id=s.cliente_id LEFT JOIN administradores a ON s.registrado_por_tipo='admin' AND a.id=s.registrado_por_id LEFT JOIN administradores t ON t.id=s.tecnico_id $where ORDER BY s.data DESC LIMIT 50");$stmt->execute($params);$solicitacoes=$stmt->fetchAll(PDO::FETCH_ASSOC);
$kpis=['abertas'=>(int)$pdo->query("SELECT COUNT(*) FROM solicitacoes WHERE status='pendente'")->fetchColumn(),'atendimento'=>(int)$pdo->query("SELECT COUNT(*) FROM solicitacoes WHERE status='em andamento'")->fetchColumn(),'aguardando'=>(int)$pdo->query("SELECT COUNT(*) FROM solicitacoes WHERE status='nao resolvido'")->fetchColumn(),'finalizadas'=>(int)$pdo->query("SELECT COUNT(*) FROM solicitacoes WHERE status='finalizado'")->fetchColumn()];
?>
