<main class="hd-main"><div class="hd-container"><section class="hd-kpis"><div class="hd-kpi"><span>O.S. abertas</span><strong><?=$kpis['abertas']?></strong><small>Aguardando triagem</small></div><div class="hd-kpi"><span>Em atendimento</span><strong><?=$kpis['atendimento']?></strong><small>Fila ativa</small></div><div class="hd-kpi"><span>Aguardando</span><strong><?=$kpis['aguardando']?></strong><small>Pendência registrada</small></div><div class="hd-kpi"><span>Finalizadas</span><strong><?=$kpis['finalizadas']?></strong><small>Histórico concluído</small></div></section>
<section class="hd-card hd-card-pad"><div class="hd-section-head"><div><h2>Atendimentos</h2><p>Últimas 50 O.S. de todos os canais.</p></div><a class="hd-btn hd-btn-primary" href="nova-os.php">➕ Nova O.S.</a></div><form method="get" class="hd-actions" style="margin-bottom:16px"><input class="hd-input" name="q" value="<?=h($q)?>" placeholder="Buscar cliente, O.S., solicitante ou equipamento"><button class="hd-btn hd-btn-outline">Buscar</button></form>
<div class="hd-table-wrap"><table class="hd-table"><thead><tr><th>O.S.</th><th>Cliente / solicitante</th><th>Origem / registro</th><th>Status</th><th>Técnico</th></tr></thead><tbody><?php if(!$solicitacoes): ?><tr><td colspan="5"><div class="hd-empty"><strong>Nenhuma O.S. encontrada</strong></div></td></tr><?php endif; ?><?php foreach($solicitacoes as $s): ?><tr><td><strong><?=h($s['protocolo']?:'#'.$s['id'])?></strong><div class="hd-ticket-meta"><?=h($s['titulo']?:mb_substr($s['descricao'],0,80))?></div><div class="hd-ticket-meta"><?=date('d/m/Y H:i',strtotime($s['data']))?></div></td><td><strong><?=h($s['cliente_nome'])?></strong><div class="hd-ticket-meta">Solicitante: <?=h($s['solicitante_nome']?:'Não informado')?></div></td><td><strong><?=h($s['canal']?:'Não informado')?></strong><div class="hd-ticket-meta">Registrado por: <?=h($s['registrado_por_nome']?:($s['registrado_por_tipo']==='cliente'?'Cliente':'Automático'))?></div></td><td><span class="hd-badge st-<?=h(str_replace(' ','-',strtolower($s['status'])))?>"><?=h(ucfirst($s['status']))?></span></td><td><?=h($s['tecnico_nome']?:'Não atribuído')?></td></tr><?php endforeach; ?></tbody></table></div></section>
